package ec.edu.unl.sec.selfassessment.domain;
import java.time.*;import java.util.*;
public record SelfAssessmentProcess(UUID id,UUID careerId,String code,String name,LocalDate periodStart,LocalDate periodEnd,UUID modelVersionId,int modelVersionNumber,ProcessState state,long revision,UUID createdBy,Instant createdAt,List<IndicatorSnapshot> indicators){public SelfAssessmentProcess{id=id==null?UUID.randomUUID():id;if(careerId==null||modelVersionId==null||createdBy==null)throw new IllegalArgumentException("required reference missing");code=req(code,100);name=req(name,300);if(periodStart==null||periodEnd==null||periodStart.isAfter(periodEnd))throw new IllegalArgumentException("invalid period");state=state==null?ProcessState.DRAFT:state;createdAt=createdAt==null?Instant.now():createdAt;indicators=indicators==null?List.of():List.copyOf(indicators);}public SelfAssessmentProcess activate(List<IndicatorSnapshot> snapshot){if(state!=ProcessState.DRAFT)throw new IllegalStateException("INVALID_PROCESS_TRANSITION");if(snapshot.isEmpty())throw new IllegalStateException("MODEL_HAS_NO_INDICATORS");return with(ProcessState.ACTIVE,revision+1,snapshot);}public SelfAssessmentProcess transition(ProcessState target){ProcessStateMachine.require(state,target);return with(target,revision+1,indicators);}private SelfAssessmentProcess with(ProcessState s,long r,List<IndicatorSnapshot> i){return new SelfAssessmentProcess(id,careerId,code,name,periodStart,periodEnd,modelVersionId,modelVersionNumber,s,r,createdBy,createdAt,i);}private static String req(String v,int max){if(v==null||v.isBlank()||v.strip().length()>max)throw new IllegalArgumentException("invalid text");return v.strip();}public record IndicatorSnapshot(UUID id,String code,String name){public IndicatorSnapshot{Objects.requireNonNull(id);code=req(code,100);name=req(name,300);}}}
